entries[164075] = { ["name"] = "Destructive Resonance: Displacement", ["text"] = "1.5 sec cast\nImperator Mar'gok summons an Arcane mine under a random enemy that arms after 3 seconds. The mine persists for 1 minute and triggers if any player enters its radius after it arms.\n\nWhen triggered, Destructive Resonance explodes, inflicting 9019 Arcane damage to all players within its radius when triggered, increasing their Arcane damage taken by 45% for 1 min.\n\nDisplacement: Destructive Resonance grows to twice its original size over 30 seconds." }
entries[164076] = { ["name"] = "Destructive Resonance: Fortification", ["text"] = "1.5 sec cast\nImperator Mar'gok summons an Arcane mine under a random enemy that arms after 3 seconds. The mine persists for 2 minute and triggers if any player enters its radius after it arms.\n\nWhen triggered, Destructive Resonance explodes, inflicting 9019 Arcane damage to all players within its radius when triggered, increasing their Arcane damage taken by 45% for 1 min.\n\nFortification: Destructive Resonance persists for 2 minutes." }
entries[164077] = { ["name"] = "Destructive Resonance: Replication", ["text"] = "1.5 sec cast\nImperator Mar'gok summons an Arcane mine under a random enemy that arms after 3 seconds. The mine persists for 1 minute and triggers if any player enters its radius after it arms.\n\nWhen triggered, Destructive Resonance explodes, inflicting 9019 Arcane damage to all players within its radius when triggered, increasing their Arcane damage taken by 45% for 1 min.\n\nReplication: When Destructive Resonance detonates or expires, two additional Destructive Resonances are created nearby." }
